import heapq


def _interval_solver(capacity, tie):
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        best_value = None
        best_ids = None

        for chosen in combinations(jobs, k):
            ids = {job["id"] for job in chosen}
            if not mandatory.issubset(ids) or ids & blocked:
                continue
            counts = {}
            for job in chosen:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            active = []
            feasible = True
            for job in sorted(chosen, key=lambda row: (row["start"], row["end"])):
                active = [end for end in active if end > job["start"]]
                active.append(job["end"])
                if len(active) > capacity:
                    feasible = False
                    break
            if not feasible:
                continue
            ordered_ids = tuple(sorted(ids))
            value = sum(job["value"] for job in chosen)
            if (best_value is None or value > best_value or
                    (value == best_value and
                     ((tie == "largest" and ordered_ids > best_ids) or
                      (tie == "smallest" and ordered_ids < best_ids)))):
                best_value, best_ids = value, ordered_ids

        if best_value is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}
    return solve


def _component_06(data):
    def rounded(numerator, mode):
        if mode == "half_up":
            return (numerator + 5000) // 10000
        return numerator // 10000

    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for position, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (event.get("revision", 0), position)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), mode)
        tax = rounded(raw * event.get("tax_bp", 0), mode)
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def _component_07(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    domains = [[-1] + sorted(row["version"] for row in packages[name])
               for name in names]
    best = None
    best_assignment = None

    for vector in product(*domains):
        assignment = dict(zip(names, vector))
        valid = True
        for name, (low, high) in roots.items():
            version = assignment[name]
            if version < 0 or not low <= version <= high:
                valid = False
                break
        if not valid:
            continue

        rows_by_name = {}
        for name, version in assignment.items():
            if version < 0:
                continue
            if version in blocked.get(name, []) or (name in pins and pins[name] != version):
                valid = False
                break
            row = next(row for row in packages[name] if row["version"] == version)
            rows_by_name[name] = row
        if not valid:
            continue

        edges = {}
        for name, row in rows_by_name.items():
            active = []
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                version = assignment[target]
                if version < 0 or not dep["min"] <= version <= dep["max"]:
                    valid = False
                    break
                active.append(target)
            if not valid:
                break
            edges[name] = active
        if not valid:
            continue

        visiting, finished = set(), set()
        def visit(name):
            if name in visiting:
                return False
            if name in finished:
                return True
            visiting.add(name)
            if any(not visit(other) for other in edges.get(name, [])):
                return False
            visiting.remove(name)
            finished.add(name)
            return True

        if not all(visit(name) for name in edges):
            continue

        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            stack.extend(edges.get(name, []))
        if reachable != set(rows_by_name):
            continue

        if best is None or vector < best:
            best = vector
            best_assignment = assignment

    if best_assignment is None:
        return {"error": "unsatisfiable"}
    return {"versions": {name: version for name, version in best_assignment.items()
                          if version >= 0}}


def _component_08(data):
    required = data.get("required", [])
    full_mask = (1 << len(required)) - 1
    initial_mask = 0
    for i, node in enumerate(required):
        if node == data["source"]:
            initial_mask |= 1 << i

    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    start_state = (data["source"], data["coupons"], initial_mask)
    distances = {start_state: data["start"]}
    queue = [(data["start"], data["source"], data["coupons"], initial_mask)]
    while queue:
        arrival, node, remaining, mask = heapq.heappop(queue)
        state = (node, remaining, mask)
        if distances.get(state) != arrival:
            continue
        if node == data["target"] and mask == full_mask:
            return {"arrival": arrival}

        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], remaining)]
            if remaining:
                options.append((max(1, edge["duration"] - edge.get("discount", 0)), remaining - 1))
            for duration, next_remaining in options:
                next_time = depart + duration
                if next_time > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask
                for i, required_node in enumerate(required):
                    if next_node == required_node:
                        next_mask |= 1 << i
                next_state = (next_node, next_remaining, next_mask)
                if next_time < distances.get(next_state, float("inf")):
                    distances[next_state] = next_time
                    heapq.heappush(queue, (next_time, next_node, next_remaining, next_mask))

    return {"arrival": None}


